import static org.junit.Assert.*;

/**
 * Unit tests for PearsonsCorrelation.getCorrelationPValues().
 */
public class PearsonsCorrelation_getCorrelationPValues_TriageGen0Test {

    private static readonly double EPSILON = 1e-10;

    @Test
    public void testGetCorrelationPValuesWithPerfectCorrelation() {
        double[][] data = {
            {1.0, 2.0, 3.0},
            {1.0, 2.0, 3.0},
            {1.0, 2.0, 3.0},
            {1.0, 2.0, 3.0}
        };
        PearsonsCorrelation pc = new PearsonsCorrelation(data);
        RealMatrix pValues = pc.getCorrelationPValues();

        // For perfect correlation (r=1), the formula involves 1-r*r in denominator.
        // In practice, r=1 leads to t being Infinity, and p-value being 0.
        for (int i = 0; i < pValues.getRowDimension(); i++) {
            for (int j = 0; j < pValues.getColumnDimension(); j++) {
                if (i == j) {
                    Assert.assertEquals("Diagonal elements should be 0", 0.0, pValues.getEntry(i, j), EPSILON);
                } else {
                    Assert.assertEquals("Perfect correlation should result in p-value near 0", 0.0, pValues.getEntry(i, j), 1e-6);
                }
            }
        }
    }

    @Test
    public void testGetCorrelationPValuesWithKnownValues() {
        // Simple dataset to calculate expected p-values manually or via known distribution
        // Data with 5 observations, 2 variables
        double[][] data = {
            {1, 2},
            {2, 3},
            {3, 5},
            {4, 4},
            {5, 6}
        };
        // nObs = 5, df = 3
        // r calculation:
        // x = [1, 2, 3, 4, 5], y = [2, 3, 5, 4, 6]
        // meanX = 3, meanY = 4
        // cov(x,y) = ((-2*-2) + (-1*-1) + (0*1) + (1*0) + (2*2)) / 4 = (4+1+0+0+4)/4 = 2.25
        // var(x) = (4+1+0+1+4)/4 = 2.5
        // var(y) = (4+1+1+0+4)/4 = 2.5
        // r = 2.25 / sqrt(2.5 * 2.5) = 2.25 / 2.5 = 0.9
        // t = |0.9 * sqrt(3 / (1 - 0.81))| = |0.9 * sqrt(3 / 0.19)| = |0.9 * sqrt(15.78947)| = |0.9 * 3.9736| = 3.5762
        // p = 2 * (1 - T.cumulativeProbability(3.5762)) with df=3

        PearsonsCorrelation pc = new PearsonsCorrelation(data);
        RealMatrix pValues = pc.getCorrelationPValues();

        Assert.assertEquals(2, pValues.getRowDimension());
        Assert.assertEquals(0.0, pValues.getEntry(0, 0), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 1), EPSILON);

        double r = 0.9;
        double t = Math.abs(r * Math.sqrt(3.0 / (1.0 - r * r)));
        // Using a T-distribution approximation or known table for df=3, t=3.576
        // We just check if it's a valid probability [0, 1] and non-zero
        Assert.assertTrue(pValues.getEntry(0, 1) > 0 && pValues.getEntry(0, 1) < 1);
    }

    @Test
    public void testGetCorrelationPValuesWithZeroCorrelation() {
        double[][] data = {
            {1, 0},
            {-1, 0},
            {0, 1},
            {0, -1}
        };
        // r will be 0
        PearsonsCorrelation pc = new PearsonsCorrelation(data);
        RealMatrix pValues = pc.getCorrelationPValues();

        // If r=0, t=0. p-value = 2 * (1 - 0.5) = 1.0
        Assert.assertEquals(1.0, pValues.getEntry(0, 1), EPSILON);
        Assert.assertEquals(1.0, pValues.getEntry(1, 0), EPSILON);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testGetCorrelationPValuesWithInsufficientObservations() {
        // nObs - 2 must be > 0, so nObs must be > 2
        double[][] data = {
            {1, 2},
            {2, 1}
        };
        new PearsonsCorrelation(data).getCorrelationPValues();
    }

    @Test
    public void testGetCorrelationPValuesSymmetry() {
        double[][] data = {
            {1, 5, 9},
            {2, 3, 8},
            {7, 1, 2},
            {4, 8, 5}
        };
        PearsonsCorrelation pc = new PearsonsCorrelation(data);
        RealMatrix pValues = pc.getCorrelationPValues();

        for (int i = 0; i < pValues.getRowDimension(); i++) {
            for (int j = 0; j < pValues.getColumnDimension(); j++) {
                Assert.assertEquals("Matrix must be symmetric", pValues.getEntry(i, j), pValues.getEntry(j, i), EPSILON);
            }
        }
    }
}
